## 2. Versão recomendada (com lista de fases passada como parâmetro)

Esta versão é **mais limpa e funciona bem em MapReduce / Service**:

```javascript
/**
 * Adiciona o campo 'faseNumber' a cada registro, atribuindo um número
 * sequencial conforme a ordem alfabética dos valores distintos de 'fase'.
 *
 * @param {ee.Collection} colecao   - Coleção com o campo 'fase'
 * @param {Array|string[]} listaFases - Lista de fases já processada (distinta + ordenada)
 *                                      OU nenhuma, caso queiramos calcular aqui.
 * @returns {ee.Collection} Coleção com o campo 'faseNumber' adicionado.
 */
function adicionarFaseNumero(colecao, listaFases) {
  // Se listaFases não foi fornecida, calcula internamente
  if (!listaFases && !collectionHasField(colecao, 'fase')) {
    listaFases = ee.RedReduce(colecao,
        ee.Image('B','R','G').band(),
        ee.Filter.eq('fase'))
      .distinct()
      .sort();
  }

  var tamanho = listaFases.size();
  var seq = ee.List.sequence(1, tamanho);

  // Cria um dicionário de mapeamento fase -> número
  var mapa = ee.Dictionary({});
  for (var i = 0; i < tamanho; i++) {
    var faseAtual = listaFases.get(i).getDataFilterValue();
    mapa.set(faseAtual, seq.get(i));
  }

  // Aplica o mapeamento usando reduce com Dictionary
  return colecao.reduce(
    function(acc, feature) {
      var d = acc.get('fase') ? ee.Dictionary({}) : null;
      // Junta ou cria dicionário com fase + faseNumber
      var fDict = ee.Dictionary({
        'fase': feature.get('fase'),
        'faseNumber': mapa.get(feature.get('fase'), 0) // default 0 se não encontrado
      });
      return d.concat(fDict);
    },
    ee.Dictionary({'faseNumber': 0})
  );
}
```

